                if (data.emptyFinish > 0 && data.emptyFinish - data.eventStart < 1.0 / self.targetFps || data.animated) {
                  var newFinish = data.eventStart + 1.0 / self.targetFps;
                  data.emptyFinish = newFinish;
                  data.eventFinish = newFinish;
                  eventSplitted = true;
                }
