      height = 0;
    } else {
      var sgn = scalefactor < 1 ? -1 : 1;
      var newH = height;
      if (sgn * newH * scalefactor <= sgn * self.prescaleHeightLimit) newH *= scalefactor;else if (sgn * newH < sgn * self.prescaleHeightLimit) newH = self.prescaleHeightLimit;
