    var videoSize = null;
    top = top || 0;
    left = left || 0;
    if ((!width || !height) && self.video) {
      videoSize = self.getVideoPosition();
      var newSize = _computeCanvasSize(videoSize.width * self.pixelRatio, videoSize.height * self.pixelRatio);
