    self.worker.postMessage({
      target: 'set-track-by-url',
      url: url
    });
    self.resetRenderAheadCache(false);
  };
  self.setTrack = function (content) {
    self.worker.postMessage({
      target: 'set-track',
      content: content
    });
    self.resetRenderAheadCache(false);
  };
  self.freeTrack = function (content) {
    self.worker.postMessage({
      target: 'free-track'
    });
    self.resetRenderAheadCache(false);
  };
